answer:
(async () => {
  const w_slots = {
  "values": [
    1,
    2,
    3,
    4
  ],
  "initial": 0,
  "op": "sum"
};
  const w_answer = await (async () => {
const slots = w_slots;
if (slots.op === "sum") { return slots.values.reduce((sum, value) => sum + value, slots.initial); }
if (slots.op === "product") { return slots.values.reduce((sum, value) => sum * value, slots.initial); }
if (slots.op === "minimum") { return Math.min(...slots.values); }
if (slots.op === "maximum") { return Math.max(...slots.values); }
if (slots.op === "mean") { return slots.values.reduce((sum, value) => sum + value, slots.initial) / slots.values.length; }
throw new Error("unsupported operation: " + slots.op);
  })();
  console.log(String(w_answer));
})();

